import{_ as i,l as s,o as e,c as l,v as r,p as n,x as o,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"浏览器沙箱","description":"","frontmatter":{"title":"浏览器沙箱","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/browser-sandbox.md","filePath":"cs/browser-sandbox.md","lastUpdated":1789023840000}'),c={name:"cs/browser-sandbox.md"};function B(m,a,E,_,u,b){const t=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="浏览器沙箱" tabindex="-1">浏览器沙箱 <a class="header-anchor" href="#浏览器沙箱" aria-label="Permalink to &quot;浏览器沙箱&quot;">​</a></h1><div class="epigraph"><p>渲染进程处理最脏的输入，应几乎没有系统调用权。沙箱是委派：内核强制的作业/seccomp/席位，加上进程间只传窄 IPC。假设渲染器会被打穿。</p><footer>—— 据 Barth, Jackson and Reis 对浏览器安全的论述；Chromium 沙箱文档；对照 Reis 与 Google 的站点隔离</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/sanitizers">sanitizer</a>在开发期抓洞。缺口是<strong>运行期爆炸半径</strong>：浏览器把不可信 HTML 当载荷。本课收多进程与系统调用过滤，不给逃逸步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单进程浏览器里，页面洞等于全用户权。多进程：渲染器低权，浏览器进程持密钥与文件。站点隔离减少同源逃逸。缺口是权限最小化，不是再讲 JS 引擎优化。</p><h3 id="gpu-与插件" tabindex="-1">GPU 与插件 <a class="header-anchor" href="#gpu-与插件" aria-label="Permalink to &quot;GPU 与插件&quot;">​</a></h3><p>每个特权进程都是逃逸面。TCB 要清单化。</p><p><span class="marginnote">Chromium 设计文档公开。本课禁止沙箱逃逸教程。后课容器逃逸是另一隔离层。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：站点→渲染器（受限）→IPC→浏览器（特权）。对照 seccomp-bpf、Windows 作业对象。指出内核洞仍能逃——内核是共同 TCB。</p>',12)),(e(),n(p,null,{default:o(()=>[h(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20WEB%5B%22%E4%B8%8D%E5%8F%AF%E4%BF%A1%E9%A1%B5%E9%9D%A2%22%5D%20--%3E%20REN%5B%22%E4%BD%8E%E6%9D%83%E6%B8%B2%E6%9F%93%E8%BF%9B%E7%A8%8B%22%5D%0A%20%20REN%20--%3E%20IPC%5B%22%E7%AA%84%20IPC%22%5D%0A%20%20IPC%20--%3E%20BR%5B%22%E6%B5%8F%E8%A7%88%E5%99%A8%E8%BF%9B%E7%A8%8B%22%5D%0A%20%20KER%5B%22%E5%86%85%E6%A0%B8%22%5D%20--%3E%20TCB%5B%22%E5%85%B1%E5%90%8C%20TCB%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>软件安全从「无洞」退到「有洞也不等于有整个机器」。下一课供应链：SBOM 与可复现，洞可能来自依赖而不是你的 C。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课无逃逸 PoC。SBOM 与可复现构建下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>sanitizer 发现；沙箱限制渲染器权限。</li><li>假设渲染器被打穿；IPC 要窄。</li><li>内核仍是 TCB。</li><li>下一课 SBOM 与可复现构建。</li><li>出处：Barth, Jackson and Reis；Chromium sandbox；Reis et al. 站点隔离。</li></ul>',8))])}const P=i(c,[["render",B]]);export{C as __pageData,P as default};
